{
  "name": "@yangzhe1991/opencode-glm-quota",
  "version": "0.1.0",
  "description": "OpenCode CLI plugin: GLM Coding Plan quota badge in the status bar (5h & weekly window usage, account-level real data from the official quota API) | OpenCode 状态栏 GLM Coding Plan 套餐额度徽章（5 小时/周窗口用量，官方额度 API 的账号级真实数据）",
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "tui.ts",
    "index.ts",
    "README.zh.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yangzhe1991/opencode-glm-quota.git"
  },
  "homepage": "https://github.com/yangzhe1991/opencode-glm-quota",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "glm",
    "zhipu",
    "coding-plan",
    "quota"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.28",
    "@opentui/core": "0.6.3",
    "@opentui/solid": "0.6.3",
    "solid-js": "1.9.12",
    "typescript": "^5.6.0"
  },
  "license": "MIT"
}
